head=s[:i]
tail='''/**
 * The page an issue alert links to: the issue inside its workspace and
 * project. `null` when any link in that chain no longer resolves, so the
 * caller sends nothing rather than a dead link.
 */
export async function issueLink(
  orgId: OrgId,
  issue: Issue,
): Promise<string | null> {
  const org = await orgRepo.findOrgById(orgId);
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (!org || !project) return null;
  return issuePath(org.slug, project.slug, issue.number);
}

/**
 * The bus wiring. Attached at module load rather than from `event-registry`
 * because the fan-out has no other public entry point — importing this module
 * is what makes an org start receiving notifications.
 */
let registered = false;

async function notifyAssigned(
  orgId: OrgId,
  actorId: UserId | null,
  issue: Issue,
  assigneeId: UserId,
): Promise<void> {
  const href = await issueLink(orgId, issue);
  if (href === null) return;

  await notify(orgId, "issue_assigned", [assigneeId], {
    title: "You were assigned an issue",
    body: `Issue ${issue.id} is now yours`,
    href,
    actorId,
  });
}

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  // Being assigned at creation is an assignment; `notify` drops it when the
  // creator is the assignee.
  subscribe("issue.created", async (payload) => {
    if (payload.assigneeId === null) return;
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (issue) {
      await notifyAssigned(payload.orgId, payload.actorId, issue, payload.assigneeId);
    }
  });

  subscribe("issue.assigned", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (issue) {
      await notifyAssigned(payload.orgId, payload.actorId, issue, payload.assigneeId);
    }
  });

  // Whoever moved the card (board or otherwise) is the actor, and `notify`
  // never tells the actor about their own change.
  subscribe("issue.status_changed", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue || issue.assigneeId === null) return;

    const href = await issueLink(payload.orgId, issue);
    if (href === null) return;

    await notify(payload.orgId, "issue_status_changed", [issue.assigneeId], {
      title: "Issue status changed",
      body: `Issue ${issue.id} moved from ${payload.from} to ${payload.to}`,
      href,
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue) return;

    const href = await issueLink(payload.orgId, issue);
    if (href === null) return;

    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href,
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue) return;

    const href = await issueLink(payload.orgId, issue);
    if (href === null) return;

    const watchers = [
      issue.authorId,
      ...(issue.assigneeId ? [issue.assigneeId] : []),
    ];

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href,
          actorId: payload.actorId,
        },
      );
    }
  });

  // The owner is told about everyone who joins, never the joiner. The alert
  // is not attributed to the joiner as an actor, so the owner is not dropped
  // by the actor rule either.
  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    const owners = (
      await memberRepo.listUserIdsWithRole(payload.orgId, "owner")
    ).filter((ownerId) => ownerId !== payload.userId);

    await notify(payload.orgId, "member_joined", owners, {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href: settingsPath(org.slug, "members"),
      actorId: null,
    });
  });

  // A refusal alert goes to the owners whoever tried, so no actor is passed.
  // While an owner's copy is still unread, a repeat refusal for the same
  // resource adds nothing.
  subscribe("billing.limit_refused", async (payload) => {
    const org = await orgRepo.findOrgById(payload.orgId);
    if (!org) return;

    const title = `Plan limit reached: ${payload.scopeLabel}`;
    const owners = await memberRepo.listUserIdsWithRole(payload.orgId, "owner");

    const recipients: UserId[] = [];
    for (const ownerId of owners) {
      const alreadyAlerted = await notificationRepo.hasUnreadInApp(
        payload.orgId,
        ownerId,
        "plan_limit_reached",
        title,
      );
      if (!alreadyAlerted) recipients.push(ownerId);
    }

    await notify(payload.orgId, "plan_limit_reached", recipients, {
      title,
      body: `The ${org.plan} plan allows ${payload.limit}; ${payload.used} in use`,
      href: settingsPath(org.slug, "billing"),
      actorId: null,
    });
  });
}

registerFanOut();
